const ease = [0.22, 1, 0.36, 1] as const;

export function getRevealMotion(reducedMotion: boolean) {
  if (reducedMotion) {
    return {
      initial: { opacity: 0 },
      whileInView: { opacity: 1 },
      viewport: { once: true, amount: 0.2 },
      transition: { duration: 0.2 }
    };
  }

  return {
    initial: { opacity: 0, y: 18 },
    whileInView: { opacity: 1, y: 0 },
    viewport: { once: true, amount: 0.2 },
    transition: { duration: 0.55, ease }
  };
}

export const subtleHover = { y: -3, scale: 1.01 };
export const subtleTap = { scale: 0.98 };

export function getTextSegmentMotion(reducedMotion: boolean) {
  if (reducedMotion) return { initial: false, animate: { opacity: 1, y: 0 }, transition: { duration: 0 } };
  return { initial: { opacity: 0, y: '0.72em' }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.7, ease } };
}
